package do_.eki.yo.kisscrfinder.detection

import java.io.InputStream
import java.text.Normalizer

/**
 * Kangxi radical (1-214) of each CJK ideograph in U+3400..U+FAFF.
 * Data: assets/radicals.bin, generated by scripts/generate_radicals.py from Unihan.
 */
class RadicalTable(
    private val data: ByteArray,
) {
    /** Radical number of [c], or 0 if [c] is not a known ideograph. */
    fun radicalOf(c: Char): Int {
        val index = c.code - FIRST_CODE_POINT
        return if (index in data.indices) data[index].toInt() and 0xFF else 0
    }

    companion object {
        const val ASSET_NAME = "radicals.bin"
        private const val FIRST_CODE_POINT = 0x3400
        private const val KANGXI_RADICALS_BLOCK = 0x2F00

        fun fromStream(input: InputStream): RadicalTable = RadicalTable(input.readBytes())

        /** Display form of radical [number], e.g. 149 -> "言". */
        fun radicalChar(number: Int): String =
            Normalizer.normalize(
                String(Character.toChars(KANGXI_RADICALS_BLOCK + number - 1)),
                Normalizer.Form.NFKC,
            )
    }
}
